class Solution {
public:
    std::vector<std::vector<int>> colorRed(int n) {
        std::vector<std::vector<int>> ans;
        int tip = n % 4;
        if (tip >= 1) {
            ans.push_back({1, 1});
        }
        for (int i = 2; i <= tip; i++) {
            ans.push_back({i, 1});
            ans.push_back({i, 2 * i - 1});
        }
        for (int i = tip + 1; i < n; i += 4) {
            ans.push_back({i, 1});
            for (int j = 1; j <= i; j++) {
                ans.push_back({i + 1, 2 * j + 1});
            }
            ans.push_back({i + 2, 2});
            for (int j = 0; j <= i + 2; j++) {
                ans.push_back({i + 3, 2 * j + 1});
            }
        }
        return ans;
    }
};

class Solution {
    public int[][] colorRed(int n) {
        List<int[]> ans = new ArrayList<>();
        int tip = n % 4;
        if (tip >= 1) ans.add(new int[]{1, 1});
        for (int i = 2; i <= tip; i++) {
            ans.add(new int[]{i, 1});
            ans.add(new int[]{i, 2 * i - 1});
        }
        for (int i = tip + 1; i < n; i += 4) {
            ans.add(new int[]{i, 1});
            for (int j = 1; j <= i; j++) {
                ans.add(new int[]{i + 1, 2 * j + 1});
            }
            ans.add(new int[]{i + 2, 2});
            for (int j = 0; j <= i + 2; j++) {
                ans.add(new int[]{i + 3, 2 * j + 1});
            }
        }
        return ans.toArray(new int[ans.size()][]);
    }
}

